import React, { useState } from 'react';

import Paginate from "../components/paginate"


const Search = ({ posts,ext }) => {
  const [showPosts, setShowPosts] = useState(posts);
  const [inputValue, setInputValue] = useState();

// 著者による絞り込み
var b=[]
for (let i = 0; i < posts.length; i++) {
  b.push(posts[i].node.filename.split("]")[0].substring(1));
}
const author = [...new Set(b)];
  const selectCategory = (category) => {
    // allを選択した場合は早期return
    if (category === "all") {
      setShowPosts(posts);
      return;
    }
    search(category)
  }

// フリーキーワードでの絞り込み

  const search = (value) => {
    if (value !== "") {
      const serchedPosts = posts.filter(
        (post) =>
          Object.values(post.node).filter(
            (item) =>
              item !== undefined &&
              item !== null &&
              item.toString().toUpperCase().indexOf(value.toString().toUpperCase()) !== -1
          ).length > 0
      );
      setShowPosts(serchedPosts);
      return;
    }

    setShowPosts(posts);
    return;
  };
  const handleInputChange = (e) => {
    setInputValue(e.target.value);
    search(e.target.value);
  };


  return (
    <>
    <h2>著者による絞り込み</h2>
          {/* カテゴリー選択ボタン */}
      <details> <summary><strong>クリックして著者選択ボタンの表示</strong></summary>
      <div>
        <h4>クリックして著者で絞り込みが可能</h4>
        <button className="categorybutton" onClick={() => selectCategory("all")}>全て</button>
        {author.map((category) => (
          <button className="categorybutton" onClick={() => selectCategory(category)}>{category}</button>
        ))}
      </div>
</details>

      <div>
        <h2>フリーキーワード検索</h2>
        <input type="text" value={inputValue} onChange={handleInputChange} />
      </div>
      <h2>ファイルのダウンロード</h2>
              <p>ファイル総数：{showPosts.length}</p>
      <Paginate itemsPerPage={1000} items={showPosts}/>

    </>
  );
}

export default Search
