import * as React from "react"
import { Link } from "gatsby"

const Layout = ({ location, title, children }) => {
  const rootPath = `${__PATH_PREFIX__}/`
  const isRootPath = location.pathname === rootPath
  let header

  if (isRootPath) {
    header = (
    <>
      <h1 className="main-heading">
        <Link to="/">{title}</Link>
      </h1>
        <p>
          
    <a href="https://kyukyunyorituryo.github.io/">サイトトップ</a>、<a href="https://kyukyunyorituryo.github.io/index2.html">以前のトップページ</a>、<a href="https://www.dropbox.com/sh/269j5q9gc08pgbr/gZ2UeSOwKh">dropboxへ</a>。</p>
<p>青空文庫の本をEPUBファイルにしておいている本棚。<Link to="/">EPUBファイル</Link>、<Link to="/kindle">Kindle用mobiファイル</Link>、<Link to="/kobo">kobo用kepubファイル</Link></p>

      </>
    )
  } else {
    header = (
        <>
      <Link className="header-link-home" to="/">
        {title}
      </Link>
      <p>
    <a href="https://kyukyunyorituryo.github.io/">サイトトップ</a>
<p>青空文庫の本をEPUBファイルにしておいている本棚。<Link to="/">EPUBファイル</Link>、<Link to="/kindle">Kindle用mobiファイル</Link>、<Link to="/kobo">kobo用kepubファイル</Link></p>
  </p>
      </>
    )
  }

  return (
    <div className="global-wrapper" data-is-root-path={isRootPath}>
      <header className="global-header">{header}</header>
      <main>{children}</main>
      <footer>
        © {new Date().getFullYear()},
        {` `}
        <a href="https://github.com/kyukyunyorituryo">kyukyunyorituryo</a>
      </footer>
    </div>
  )
}

export default Layout
